export function validatePolicies(file: PolicyFile): void {
  if (file === null || typeof file !== "object" || Array.isArray(file)) {
    throw new PolicyError("MALFORMED", `validatePolicies needs a PolicyFile object`);
  }
  if (!SUPPORTED_POLICY_VERSIONS.includes((file as PolicyFile).version)) {
    throw new PolicyError("UNSUPPORTED_VERSION", `unsupported policy version ${(file as PolicyFile).version}; this build understands ${SUPPORTED_POLICY_VERSIONS.join(", ")}`);
  }

